          onNew={onConversationNew}
          onDelete={onConversationDelete}
          onRename={onConversationRename}
          refreshTrigger={conversationRefreshTrigger}
          sessionId={sessionId}
        />
      </div>
      <div className="sidebar__footer">
        <a
          href="https://github.com/cyyeh/duckdb-data-agent"
          target="_blank"
