import {
  useCallback,
  useEffect,
  useRef,
  useState,
  type ReactNode,
} from 'react';
import { AgentContext } from '../hooks/useAgent';
import { runAgentLoop, runAgentEditLoop } from '../agent/agentService';
import type { ChatMessage, ContentSegment, ToolCallResult } from '../types';
import { useSessionId } from '../hooks/useSessionId';
import { generateUUID } from '../utils/uuid';

function generateId() {
  return generateUUID();
}

export function AgentProvider({
  children,
  refreshTables,
}: {
  children: ReactNode;
  refreshTables: () => Promise<void>;
}) {
  const userSessionId = useSessionId();
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [isStreaming, setIsStreaming] = useState(false);
  const abortRef = useRef<AbortController | null>(null);
  const textBufferRef = useRef('');
  const flushTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const assistantIdRef = useRef('');
  const segmentsRef = useRef<ContentSegment[]>([]);
  const currentTextRef = useRef('');
  const phaseRef = useRef<'thinking' | 'answer'>('thinking');
  const sessionIdRef = useRef<string | null>(null);
  const pendingHistoryRef = useRef<{ role: string; content: string }[] | null>(null);
  // Keep a ref in sync with messages so sendMessage always reads the latest
  const messagesRef = useRef<ChatMessage[]>(messages);
  useEffect(() => { messagesRef.current = messages; }, [messages]);
  // Cache messages per conversation so switching away doesn't lose in-progress data
  const messagesCacheRef = useRef<Map<string, ChatMessage[]>>(new Map());
  // Track which conversation is currently displayed so background streams can detect they're stale
  const activeConversationIdRef = useRef<string | null>(null);
  // Track which conversation owns the current SSE stream (set in sendMessage).
  // Used as a fallback when React state is stale (e.g. user switches before re-render).
  const streamConversationIdRef = useRef<string | null>(null);
  // Generation counter: incremented on every stream-disrupting event (sendMessage,
  // loadMessages, clearMessages).  Callbacks capture the generation at creation time
  // and bail out if the ref has since advanced, preventing cross-conversation leaks.
  const streamGenerationRef = useRef(0);

  const flushText = useCallback(() => {
    const text = textBufferRef.current;
    if (!text) return;
    const id = assistantIdRef.current;
    currentTextRef.current += text;
    setMessages((prev) =>
      prev.map((m) =>
        m.id === id ? { ...m, content: m.content + text } : m
      )
    );
    textBufferRef.current = '';
  }, []);

  const sendMessage = useCallback(
    async (text: string, conversationId?: string | null) => {
      if (isStreaming) return;
      streamConversationIdRef.current = conversationId || null;
      const generation = ++streamGenerationRef.current;

      const userMsg: ChatMessage = {
        id: generateId(),
        role: 'user',
        content: text,
      };

      const assistantId = generateId();
      assistantIdRef.current = assistantId;
      const assistantMsg: ChatMessage = {
        id: assistantId,
        role: 'assistant',
        content: '',
        toolCalls: [],
        isStreaming: true,
      };

      setMessages((prev) => [...prev, userMsg, assistantMsg]);
      setIsStreaming(true);
      textBufferRef.current = '';
      segmentsRef.current = [];
      currentTextRef.current = '';
      phaseRef.current = 'thinking';

      // Build conversation history from current messages for resume fallback.
      // Read from messagesRef (not the stale closure `messages`) so that
      // switching conversations is reflected immediately.
      const history = messagesRef.current
        .filter((m) => m.role === 'user' || m.role === 'assistant')
        .map((m) => ({ role: m.role, content: m.content }));

      // If there's pending history from a delete, start a new Langfuse session with that context
      const pendingHistory = pendingHistoryRef.current;
      pendingHistoryRef.current = null;
      const langfuseSessionId = pendingHistory ? generateUUID() : null;

      const controller = new AbortController();
      abortRef.current = controller;

      // Extract all /skill-name references from message
      let actualMessage = text;
      let skills: string[] | undefined;
      const slashMatches = [...text.matchAll(/\/([a-z0-9-]+)/g)];
      if (slashMatches.length > 0) {
        skills = slashMatches.map((m) => m[1]);
        actualMessage = slashMatches.reduce((msg, m) => msg.replace(m[0], ''), text).trim() || text;
      }

      await runAgentLoop(
        actualMessage,
        sessionIdRef.current,
        langfuseSessionId,
        pendingHistory ?? (history.length > 0 ? history : null),
        conversationId,
        {
          onTextChunk: (chunk) => {
            if (streamGenerationRef.current !== generation) return;
            textBufferRef.current += chunk;
            if (!flushTimerRef.current) {
              flushTimerRef.current = setTimeout(() => {
                flushText();
                flushTimerRef.current = null;
              }, 50);
            }
          },
          onThinkingDone: () => {
            if (streamGenerationRef.current !== generation) return;
            // Extended thinking just ended and a text block is starting.
            // Create a thinking segment from accumulated thinking text.
            if (flushTimerRef.current) {
              clearTimeout(flushTimerRef.current);
              flushTimerRef.current = null;
            }
            flushText();
            if (currentTextRef.current.trim()) {
              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
              currentTextRef.current = '';
            }
            phaseRef.current = 'answer';
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
                  : m
              )
            );
          },
          onToolCall: (pending: ToolCallResult) => {
            if (streamGenerationRef.current !== generation) return;
            if (flushTimerRef.current) {
              clearTimeout(flushTimerRef.current);
              flushTimerRef.current = null;
            }
            flushText();
            if (currentTextRef.current.trim()) {
              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
              currentTextRef.current = '';
            }
            // Add a pending tool segment so the input is shown immediately
            segmentsRef.current.push({
              type: 'tool',
              toolResult: pending,
            });
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
                  : m
              )
            );
          },
          onToolResult: (result: ToolCallResult) => {
            if (streamGenerationRef.current !== generation) return;
            // Merge result into pending tool segment (keep input info, add output)
            const pendingIdx = segmentsRef.current.findIndex(
              (s) => s.type === 'tool' && s.toolResult?.toolCallId === result.toolCallId
            );
            if (pendingIdx !== -1) {
              const pending = segmentsRef.current[pendingIdx].toolResult!;
              segmentsRef.current[pendingIdx] = {
                type: 'tool',
                toolResult: {
                  ...pending,
                  ...result,
                  sql: result.sql || pending.sql,
                  toolName: result.toolName || pending.toolName,
                  command: result.command || pending.command,
                  toolInput: result.toolInput || pending.toolInput,
                },
              };
            } else {
              segmentsRef.current.push({ type: 'tool', toolResult: result });
            }
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, toolCalls: [...(m.toolCalls || []), result], segments: [...segmentsRef.current] }
                  : m
              )
            );
            refreshTables();
            // When a skill is created, notify SkillsPanel to refresh
            if (result.toolName?.includes('create_skill')) {
              window.dispatchEvent(new CustomEvent('skills-updated'));
            }
            // When a memory is saved or forgotten, notify MemoriesPanel to refresh
            if (result.toolName?.includes('save_memory') || result.toolName?.includes('forget_memory')) {
              window.dispatchEvent(new CustomEvent('memories-updated'));
            }
          },
          onSubagentStart: (data) => {
            if (streamGenerationRef.current !== generation) return;
            if (flushTimerRef.current) {
              clearTimeout(flushTimerRef.current);
              flushTimerRef.current = null;
            }
            flushText();
            if (currentTextRef.current.trim()) {
              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
              currentTextRef.current = '';
            }
            segmentsRef.current.push({
              type: 'subagent_start',
              subagentId: data.id,
              subagentName: data.name,
              text: data.prompt,
            });
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, segments: [...segmentsRef.current] }
                  : m
              )
            );
          },
          onSubagentEnd: (data) => {
            if (streamGenerationRef.current !== generation) return;
            segmentsRef.current.push({
              type: 'subagent_end',
              subagentId: data.id,
              subagentName: data.name,
              chart_spec: data.chart_spec,
              sqlResults: data.sql_results,
              text: data.result,
            });
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, segments: [...segmentsRef.current] }
                  : m
              )
            );
          },
          onDone: (newSessionId) => {
            // If this stream's generation is stale (user switched conversations
            // or started a new stream), don't touch shared state — just clear
            // the stale cache so the next switch loads the full backend response.
            if (streamGenerationRef.current !== generation) {
              if (conversationId) messagesCacheRef.current.delete(conversationId);
              return;
            }
            if (newSessionId) sessionIdRef.current = newSessionId;
            if (flushTimerRef.current) {
              clearTimeout(flushTimerRef.current);
              flushTimerRef.current = null;
            }
            flushText();
            if (currentTextRef.current.trim()) {
              segmentsRef.current.push({
                type: 'answer',
                text: currentTextRef.current,
              });
              currentTextRef.current = '';
            }
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...segmentsRef.current] }
                  : m
              )
            );
            setIsStreaming(false);
            abortRef.current = null;
          },
          onError: (error) => {
            if (streamGenerationRef.current !== generation) {
              if (conversationId) messagesCacheRef.current.delete(conversationId);
              return;
            }
            if (flushTimerRef.current) {
              clearTimeout(flushTimerRef.current);
              flushTimerRef.current = null;
            }
            flushText();
            if (currentTextRef.current.trim()) {
              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
              currentTextRef.current = '';
            }
            segmentsRef.current.push({ type: 'error', errorMessage: error });
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...segmentsRef.current] }
                  : m
              )
            );
            setIsStreaming(false);
            abortRef.current = null;
          },
          onUserQuestion: (data) => {
            if (streamGenerationRef.current !== generation) return;
            if (flushTimerRef.current) {
              clearTimeout(flushTimerRef.current);
              flushTimerRef.current = null;
            }
            flushText();
            if (currentTextRef.current.trim()) {
              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
              currentTextRef.current = '';
            }
            segmentsRef.current.push({
              type: 'user_question',
              questionData: data,
            });
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, segments: [...segmentsRef.current] }
                  : m
              )
            );
          },
        },
        controller.signal,
        userSessionId,
        skills,
      );
    },
    [isStreaming, flushText, refreshTables, userSessionId]
  );

  const editMessage = useCallback(
    async (messageIndex: number, newContent: string) => {
      if (isStreaming) return;
      const generation = ++streamGenerationRef.current;

      // Build conversation history from messages before the edit point
      const conversationHistory: { role: string; content: string }[] = [];
      for (let i = 0; i < messageIndex; i++) {
        const msg = messages[i];
        if (msg.role === 'user' || msg.role === 'assistant') {
          conversationHistory.push({ role: msg.role, content: msg.content });
        }
      }

      const assistantId = generateId();
      assistantIdRef.current = assistantId;

      const userMsg: ChatMessage = {
        id: generateId(),
        role: 'user',
        content: newContent,
      };
      const assistantMsg: ChatMessage = {
        id: assistantId,
        role: 'assistant',
        content: '',
        toolCalls: [],
        isStreaming: true,
      };

      setMessages((prev) => [...prev.slice(0, messageIndex), userMsg, assistantMsg]);
      setIsStreaming(true);
      textBufferRef.current = '';
      segmentsRef.current = [];
      currentTextRef.current = '';
      phaseRef.current = 'thinking';

      const controller = new AbortController();
      abortRef.current = controller;

      await runAgentEditLoop(
        newContent,
        conversationHistory,
        generateUUID(),
        {
          onTextChunk: (chunk) => {
            if (streamGenerationRef.current !== generation) return;
            textBufferRef.current += chunk;
            if (!flushTimerRef.current) {
              flushTimerRef.current = setTimeout(() => {
                flushText();
                flushTimerRef.current = null;
              }, 50);
            }
          },
          onThinkingDone: () => {
            if (streamGenerationRef.current !== generation) return;
            if (flushTimerRef.current) {
              clearTimeout(flushTimerRef.current);
              flushTimerRef.current = null;
            }
            flushText();
            if (currentTextRef.current.trim()) {
              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
              currentTextRef.current = '';
            }
            phaseRef.current = 'answer';
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
                  : m
              )
            );
          },
          onToolCall: (pending: ToolCallResult) => {
            if (streamGenerationRef.current !== generation) return;
            if (flushTimerRef.current) {
              clearTimeout(flushTimerRef.current);
              flushTimerRef.current = null;
            }
            flushText();
            if (currentTextRef.current.trim()) {
              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
              currentTextRef.current = '';
            }
            segmentsRef.current.push({ type: 'tool', toolResult: pending });
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
                  : m
              )
            );
          },
          onToolResult: (result: ToolCallResult) => {
            if (streamGenerationRef.current !== generation) return;
            const pendingIdx = segmentsRef.current.findIndex(
              (s) => s.type === 'tool' && s.toolResult?.toolCallId === result.toolCallId
            );
            if (pendingIdx !== -1) {
              const pending = segmentsRef.current[pendingIdx].toolResult!;
              segmentsRef.current[pendingIdx] = {
                type: 'tool',
                toolResult: {
                  ...pending,
                  ...result,
                  sql: result.sql || pending.sql,
                  toolName: result.toolName || pending.toolName,
                  command: result.command || pending.command,
                  toolInput: result.toolInput || pending.toolInput,
                },
              };
            } else {
              segmentsRef.current.push({ type: 'tool', toolResult: result });
            }
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, toolCalls: [...(m.toolCalls || []), result], segments: [...segmentsRef.current] }
                  : m
              )
            );
            refreshTables();
          },
          onSubagentStart: (data) => {
            if (streamGenerationRef.current !== generation) return;
            if (flushTimerRef.current) {
              clearTimeout(flushTimerRef.current);
              flushTimerRef.current = null;
            }
            flushText();
            if (currentTextRef.current.trim()) {
              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
              currentTextRef.current = '';
            }
            segmentsRef.current.push({
              type: 'subagent_start',
              subagentId: data.id,
              subagentName: data.name,
              text: data.prompt,
            });
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, segments: [...segmentsRef.current] }
                  : m
              )
            );
          },
          onSubagentEnd: (data) => {
            if (streamGenerationRef.current !== generation) return;
            segmentsRef.current.push({
              type: 'subagent_end',
              subagentId: data.id,
              subagentName: data.name,
              chart_spec: data.chart_spec,
              sqlResults: data.sql_results,
              text: data.result,
            });
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, segments: [...segmentsRef.current] }
                  : m
              )
            );
          },
          onDone: (newSessionId) => {
            if (streamGenerationRef.current !== generation) return;
            if (newSessionId) sessionIdRef.current = newSessionId;
            if (flushTimerRef.current) {
              clearTimeout(flushTimerRef.current);
              flushTimerRef.current = null;
            }
            flushText();
            if (currentTextRef.current.trim()) {
              segmentsRef.current.push({ type: 'answer', text: currentTextRef.current });
              currentTextRef.current = '';
            }
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...segmentsRef.current] }
                  : m
              )
            );
            setIsStreaming(false);
            abortRef.current = null;
          },
          onError: (error) => {
            if (streamGenerationRef.current !== generation) return;
            if (flushTimerRef.current) {
              clearTimeout(flushTimerRef.current);
              flushTimerRef.current = null;
            }
            flushText();
            if (currentTextRef.current.trim()) {
              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
              currentTextRef.current = '';
            }
            segmentsRef.current.push({ type: 'error', errorMessage: error });
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...segmentsRef.current] }
                  : m
              )
            );
            setIsStreaming(false);
            abortRef.current = null;
          },
          onUserQuestion: (data) => {
            if (streamGenerationRef.current !== generation) return;
            if (flushTimerRef.current) {
              clearTimeout(flushTimerRef.current);
              flushTimerRef.current = null;
            }
            flushText();
            if (currentTextRef.current.trim()) {
              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
              currentTextRef.current = '';
            }
            segmentsRef.current.push({
              type: 'user_question',
              questionData: data,
            });
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, segments: [...segmentsRef.current] }
                  : m
              )
            );
          },
        },
        controller.signal,
        userSessionId,
      );
    },
    [isStreaming, messages, flushText, refreshTables, userSessionId]
  );

  const deleteMessage = useCallback(
    (messageIndex: number) => {
      if (isStreaming) return;

      // Store remaining messages as history for Langfuse context on next send
      setMessages((prev) => {
        const remaining = prev.slice(0, messageIndex);
        pendingHistoryRef.current = remaining
          .filter((m) => m.role === 'user' || m.role === 'assistant')
          .map((m) => ({ role: m.role, content: m.content }));
        return remaining;
      });

      // Clear session so next message starts fresh
      sessionIdRef.current = null;
    },
    [isStreaming]
  );

  const respondToQuestion = useCallback(
    async (questionId: string, answers: string[], freeText?: string) => {
      // Update the segment to show the user's answer
      const segIdx = segmentsRef.current.findIndex(
        (s) => s.type === 'user_question' && s.questionData?.questionId === questionId
      );
      if (segIdx !== -1) {
        segmentsRef.current[segIdx] = {
          ...segmentsRef.current[segIdx],
          userAnswer: answers,
          userFreeText: freeText,
        };
        setMessages((prev) =>
          prev.map((m) =>
            m.id === assistantIdRef.current
              ? { ...m, segments: [...segmentsRef.current] }
              : m
          )
        );
      }

      // POST to backend
      try {
        await fetch('/api/chat/respond', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            ...(userSessionId ? { 'X-Session-ID': userSessionId } : {}),
          },
          body: JSON.stringify({
            question_id: questionId,
            answers,
            free_text: freeText || null,
          }),
        });
      } catch (e) {
        console.error('Failed to respond to question:', e);
      }
    },
    [userSessionId]
  );

  const loadMessages = useCallback((msgs: ChatMessage[], outgoingConversationId?: string | null, incomingConversationId?: string | null) => {
    // Invalidate any in-flight stream so its callbacks become no-ops.
    ++streamGenerationRef.current;

    // Fall back to the stream's conversation ID when React state is stale
    // (e.g. user switches before re-render after createConversation).
    const outgoing = outgoingConversationId || streamConversationIdRef.current;
    activeConversationIdRef.current = incomingConversationId || null;

    // Don't abort the SSE stream — let the backend agent continue running
    // in the background.  The onDone/onError callbacks detect that the
    // conversation has changed and handle cleanup (cache invalidation).
    // Only clear the flush timer so it doesn't interfere with the new
    // conversation's state.
    if (flushTimerRef.current) {
      clearTimeout(flushTimerRef.current);
      flushTimerRef.current = null;
    }

    // Prefer cached messages when the cache is at least as complete as
    // the backend response (cache keeps rich segments / streaming data).
    let finalMsgs = msgs;
    if (incomingConversationId) {
      const cached = messagesCacheRef.current.get(incomingConversationId);
      if (cached && cached.length > 0 && cached.length >= msgs.length) {
        finalMsgs = cached;
      }
      // Clear used cache entry so stale data doesn't persist forever
      messagesCacheRef.current.delete(incomingConversationId);
    }

    // Capture ref values NOW — React 18 batching may defer the updater
    // function below until after the ref resets at the bottom of this
    // function, so reading refs inside the updater would see empty values.
    const capturedTextBuffer = textBufferRef.current;
    const capturedAssistantId = assistantIdRef.current;
    const capturedSegments = [...segmentsRef.current];
    const capturedCurrentText = currentTextRef.current;
    const capturedPhase = phaseRef.current;

    // Save current messages to cache before replacing them.
    setMessages(prev => {
      if (outgoing && prev.length > 0) {
        const pendingText = capturedTextBuffer;
        const aId = capturedAssistantId;

        // Build finalized segments including any unflushed text
        let finalSegments = [...capturedSegments];
        const pendingSegmentText = capturedCurrentText + pendingText;
        if (pendingSegmentText.trim()) {
          const segType = capturedPhase === 'answer' ? 'answer' : 'thinking';
          finalSegments.push({ type: segType as ContentSegment['type'], text: pendingSegmentText });
        }

        const cleaned = prev.map(m => {
          if (m.id === aId && m.isStreaming) {
            return {
              ...m,
              content: m.content + pendingText,
              // Keep isStreaming: true — the SSE stream continues in
              // the background so the UI should show a thinking indicator.
              segments: finalSegments.length > 0 ? finalSegments : m.segments,
            };
          }
          return m;
        });
        // Filter out completed-but-empty assistant messages. Streaming
        // messages are always kept so the thinking indicator stays visible.
        const toCache = cleaned.filter(m => {
          if (m.role === 'assistant' && !m.isStreaming && !m.content?.trim() && (!m.segments || m.segments.length === 0)) {
            return false;
          }
          return true;
        });
        messagesCacheRef.current.set(outgoing, toCache);
      }
      return finalMsgs;
    });

    setIsStreaming(false);
    textBufferRef.current = '';
    currentTextRef.current = '';
    segmentsRef.current = [];
    assistantIdRef.current = '';
    phaseRef.current = 'thinking';
    sessionIdRef.current = null;
    pendingHistoryRef.current = null;
  }, []);

  const clearMessages = useCallback((outgoingConversationId?: string | null) => {
    ++streamGenerationRef.current;
    const outgoing = outgoingConversationId || streamConversationIdRef.current;
    activeConversationIdRef.current = null;
    if (abortRef.current) {
      abortRef.current.abort();
      abortRef.current = null;
    }
    if (flushTimerRef.current) {
      clearTimeout(flushTimerRef.current);
      flushTimerRef.current = null;
    }

    // Capture refs before setMessages (React 18 batching may defer the updater)
    const capturedTextBuffer = textBufferRef.current;
    const capturedAssistantId = assistantIdRef.current;
    const capturedSegments = [...segmentsRef.current];
    const capturedCurrentText = currentTextRef.current;
    const capturedPhase = phaseRef.current;

    setMessages(prev => {
      if (outgoing && prev.length > 0) {
        const pendingText = capturedTextBuffer;
        const aId = capturedAssistantId;
        let finalSegments = [...capturedSegments];
        const pendingSegmentText = capturedCurrentText + pendingText;
        if (pendingSegmentText.trim()) {
          const segType = capturedPhase === 'answer' ? 'answer' : 'thinking';
          finalSegments.push({ type: segType as ContentSegment['type'], text: pendingSegmentText });
        }
        const cleaned = prev.map(m => {
          if (m.id === aId && m.isStreaming) {
            return {
              ...m,
              content: m.content + pendingText,
              isStreaming: false,
              currentPhase: undefined,
              segments: finalSegments.length > 0 ? finalSegments : m.segments,
            };
          }
          return m.isStreaming ? { ...m, isStreaming: false, currentPhase: undefined } : m;
        });
        const toCache = cleaned.filter(m => {
          if (m.role === 'assistant' && !m.content?.trim() && (!m.segments || m.segments.length === 0)) {
            return false;
          }
          return true;
        });
        messagesCacheRef.current.set(outgoing, toCache);
      }
      return [];
    });
    setIsStreaming(false);
    textBufferRef.current = '';
    currentTextRef.current = '';
    segmentsRef.current = [];
    assistantIdRef.current = '';
    phaseRef.current = 'thinking';
    sessionIdRef.current = null;
    pendingHistoryRef.current = null;
  }, []);

  return (
    <AgentContext.Provider
      value={{ messages, isStreaming, sendMessage, editMessage, deleteMessage, clearMessages, loadMessages, respondToQuestion }}
    >
      {children}
    </AgentContext.Provider>
  );
}

    # Track SQL queries executed inside subagents so they can be
    # included in the subagent_end event for visibility.
    subagent_sql_data: dict[str, list[dict]] = {}  # parent_tool_use_id -> [{tool_id, sql, columns?, rows?, rowCount?}]
    subagent_internal_tools: dict[str, str] = {}   # tool_id -> parent_tool_use_id

    # Timeout must exceed SDK_IDLE_TIMEOUT_MS so the sidecar's own
    # idle abort fires first; add a 60s buffer.
    httpx_timeout = (SDK_IDLE_TIMEOUT_MS / 1000) + 60
    async with httpx.AsyncClient(timeout=httpx.Timeout(httpx_timeout)) as client:
        async with client.stream("POST", f"{info.url}/query", json=payload) as response:
            line_iter = response.aiter_lines().__aiter__()
            while True:
                try:
                    if waiting_for_user:
                        try:
                            line = await asyncio.wait_for(line_iter.__anext__(), timeout=5.0)
                        except asyncio.TimeoutError:
                            yield ": keepalive\n\n"
                            continue
                    else:
                        line = await line_iter.__anext__()
                except StopAsyncIteration:
                    break
                except httpx.RemoteProtocolError:
                    # Sidecar closed the connection before sending a
                    # proper chunked-encoding terminator.  This is
                    # benign — the sidecar's Express handler calls
                    # res.end() in its finally block and the
                    # connection can tear down before the last chunk
                    # delimiter reaches us.  Treat it as end-of-stream.
                    logger.warning("Sidecar closed connection early (incomplete chunked read); treating as end-of-stream")
                    break

                if not line.startswith("data: "):
                    continue
                raw = line[6:]
                waiting_for_user = False
                try:
                    msg = json.loads(raw)
                except json.JSONDecodeError:
                    continue

                # Reset container idle timer on every message so
                # long-running queries don't trigger the reaper.
                container_manager.touch(stable_session)

                msg_type = msg.get("type")
                # --- Token-level streaming events from SDK ---
                if msg_type == "stream_event":
                    event = msg.get("event", {})
                    event_type = event.get("type", "")
                    stream_parent = msg.get("parent_tool_use_id")
                    is_subagent_event = bool(stream_parent and stream_parent in tool_names)

                    if event_type == "content_block_delta":
                        delta = event.get("delta", {})
                        delta_type = delta.get("type", "")
                        if delta_type == "thinking_delta":
                            text = delta.get("thinking", "")
                            if text and not is_subagent_event:
                                seg_thinking_buf.append(text)
                                yield f"event: thinking\ndata: {json.dumps({'text': text})}\n\n"
                        elif delta_type == "text_delta":
                            text = delta.get("text", "")
                            if text:
                                # Accumulate subagent text for chart_spec
                                # extraction (the SDK may not yield a
                                # complete assistant message for the
                                # subagent's final turn).
                                if is_subagent_event:
                                    subagent_texts[stream_parent] = subagent_texts.get(stream_parent, "") + text
                                else:
                                    event_name = "answer" if has_tool_calls else "thinking"
                                    all_text_parts.append(text)
                                    # Track text in segment buffers based on actual phase
                                    if seg_phase == "thinking":
                                        seg_thinking_buf.append(text)
                                    else:
                                        seg_answer_buf.append(text)
                                    if event_name == "answer":
                                        assistant_text_parts.append(text)
                                    yield f"event: {event_name}\ndata: {json.dumps({'text': text})}\n\n"

                    elif event_type == "content_block_start":
                        block = event.get("content_block", {})
                        block_type = block.get("type")
                        if block_type == "thinking":
                            if not is_subagent_event:
                                has_thinking = True
                        elif block_type == "text":
                            if has_thinking and not is_subagent_event:
                                # Flush thinking buffer into a segment
                                if seg_thinking_buf:
                                    persisted_segments.append({"type": "thinking", "text": "".join(seg_thinking_buf)})
                                    seg_thinking_buf.clear()
                                seg_phase = "answer"
                                yield f"event: thinking_done\ndata: {json.dumps({})}\n\n"
                        elif block_type == "tool_use":
                            if not is_subagent_event:
                                # Flush thinking buffer before tool calls
                                if seg_thinking_buf:
                                    persisted_segments.append({"type": "thinking", "text": "".join(seg_thinking_buf)})
                                    seg_thinking_buf.clear()
                                seg_phase = "answer"
                                has_thinking = False
                                has_tool_calls = True

                # --- Complete assistant message (contains tool_use blocks) ---
                elif msg_type == "assistant":
                    message_obj = msg.get("message", {})
                    parent_tool_use_id = msg.get("parent_tool_use_id")

                    # Capture text from subagent assistant messages.
                    # These carry the real subagent output (e.g. chart JSON)
                    # that the Task tool_result metadata lacks.
                    if parent_tool_use_id and parent_tool_use_id in tool_names:
                        text_parts = []
                        for block in message_obj.get("content", []):
                            if block.get("type") == "text" and block.get("text"):
                                text_parts.append(block["text"])
                        if text_parts:
                            subagent_texts[parent_tool_use_id] = "\n".join(text_parts)

                    is_subagent_msg = bool(parent_tool_use_id and parent_tool_use_id in tool_names)
                    for block in message_obj.get("content", []):
                        block_type = block.get("type")
                        if block_type == "tool_use":
                            tool_id = block.get("id", "")
                            tool_name = block.get("name", "")
                            tool_input = block.get("input", {})
                            tool_names[tool_id] = tool_name

                            # Skip emitting tool_call for subagent-internal
                            # tools (execute_sql inside sql-analyst).  The
                            # SDK doesn't yield the matching tool_result
                            # user message, so the frontend would show
                            # "Executing..." forever.
                            if is_subagent_msg:
                                subagent_internal_tools[tool_id] = parent_tool_use_id
                                # Capture SQL for subagent_end visibility
                                if "execute_sql" in tool_name:
                                    sql = tool_input.get("sql", "")
                                    if sql:
                                        subagent_sql_data.setdefault(parent_tool_use_id, []).append(
                                            {"tool_id": tool_id, "sql": sql}
                                        )
                                continue

                            has_tool_calls = True
                            is_execute_sql = "execute_sql" in tool_name
                            is_render_chart = "render_chart" in tool_name
                            sql = tool_input.get("sql", "") if is_execute_sql else ""
                            if sql:
                                tool_sqls[tool_id] = sql
                            # Capture render_chart input so we can attach
                            # chart_spec to the tool_result event.
                            if is_render_chart:
                                tool_chart_specs[tool_id] = tool_input
                            tool_call_data: dict = {"id": tool_id, "name": tool_name}
                            if sql:
                                tool_call_data["sql"] = sql
                            else:
                                tool_call_data["input"] = tool_input
                            yield f"event: tool_call\ndata: {json.dumps(tool_call_data, default=str)}\n\n"
                            # Track tool segment for persistence (placeholder, updated on result)
                            persisted_segments.append({
                                "type": "tool",
                                "toolCallId": tool_id,
                                "toolName": tool_name,
                                "sql": sql or None,
                            })
                            if tool_name == "Task":
                                subagent_name = tool_input.get("subagent_type", "unknown")
                                subagent_prompt = tool_input.get("prompt", "")
                                tool_names[tool_id] = subagent_name
                                # Replace tool segment with subagent_start for subagent tools
                                persisted_segments[-1] = {
                                    "type": "subagent_start",
                                    "subagentId": tool_id,
                                    "subagentName": subagent_name,
                                }
                                yield f"event: subagent_start\ndata: {json.dumps({'id': tool_id, 'name': subagent_name, 'prompt': subagent_prompt})}\n\n"

                            # Detect ask_user_question tool
                            if "ask_user_question" in tool_name:
                                from app.pending_questions import pending_question_store
                                import asyncio as _asyncio
                                for _ in range(50):
                                    pending = pending_question_store.get_pending(stable_session)
                                    if pending:
                                        yield f"event: user_question\ndata: {json.dumps({'question_id': pending['question_id'], **pending['data']})}\n\n"
                                        waiting_for_user = True
                                        break
                                    await _asyncio.sleep(0.1)

                # --- Tool results from user messages ---
                elif msg_type == "user":
                    message_obj = msg.get("message", {})
                    # The SDK attaches the subagent's actual output in
                    # tool_use_result.content (a list of content blocks).
                    # Extract it so we can use it for chart_spec extraction.
                    tool_use_result = msg.get("tool_use_result")
                    tool_use_result_text = ""
                    if isinstance(tool_use_result, dict):
                        tur_content = tool_use_result.get("content")
                        if isinstance(tur_content, list):
                            parts = []
                            for item in tur_content:
                                if isinstance(item, dict) and item.get("type") == "text":
                                    parts.append(item.get("text", ""))
                            tool_use_result_text = "\n".join(parts)
                    for block in message_obj.get("content", []):
                        if block.get("type") != "tool_result":
                            continue
                        tool_id = block.get("tool_use_id", "")

                        # Skip subagent-internal tool results; capture
                        # structured data for inclusion in subagent_end.
                        parent_subagent_id = subagent_internal_tools.get(tool_id)
                        if parent_subagent_id:
                            sa_name = tool_names.get(tool_id, "")
                            if "execute_sql" in sa_name:
                                sa_parts = block.get("content", [])
                                sa_text = ""
                                if isinstance(sa_parts, list):
                                    for part in sa_parts:
                                        if isinstance(part, dict) and part.get("type") == "text":
                                            sa_text = part.get("text", "")
                                elif isinstance(sa_parts, str):
                                    sa_text = sa_parts
                                try:
                                    sa_parsed = json.loads(sa_text)
                                    for entry in subagent_sql_data.get(parent_subagent_id, []):
                                        if entry.get("tool_id") == tool_id:
                                            if sa_parsed.get("status") == "success":
                                                entry["columns"] = sa_parsed.get("columns", [])
                                                entry["rows"] = sa_parsed.get("rows", [])[:100]
                                                entry["rowCount"] = sa_parsed.get("rowCount", 0)
                                            elif sa_parsed.get("status") == "error":
                                                entry["error"] = sa_parsed.get("error", "")
                                            break
                                except (json.JSONDecodeError, AttributeError):
                                    pass
                            continue

                        name = tool_names.get(tool_id, "")
                        content_parts = block.get("content", [])
                        text = ""
                        if isinstance(content_parts, list):
                            for part in content_parts:
                                if isinstance(part, dict) and part.get("type") == "text":
                                    text = part.get("text", "")
                        elif isinstance(content_parts, str):
                            text = content_parts

                        # Try to parse structured MCP result
                        result_data: dict = {"id": tool_id, "name": name}
                        # Include the SQL from the original tool_call
                        original_sql = tool_sqls.get(tool_id, "")
                        if original_sql:
                            result_data["sql"] = original_sql
                        try:
                            parsed = json.loads(text)
                            if parsed.get("status") == "success":
                                if "chart_spec" in parsed:
                                    result_data["chart_spec"] = parsed["chart_spec"]
                                else:
                                    result_data["columns"] = parsed.get("columns", [])
                                    result_data["rows"] = parsed.get("rows", [])[:100]
                                    result_data["rowCount"] = parsed.get("rowCount", 0)
                            elif parsed.get("status") == "error":
                                result_data["error"] = parsed.get("error", "")
                            else:
                                result_data["output"] = text
                        except (json.JSONDecodeError, AttributeError):
                            result_data["output"] = text
                        if block.get("is_error"):
                            try:
                                parsed_err = json.loads(text)
                                result_data["error"] = parsed_err.get("error", text)
                            except (json.JSONDecodeError, AttributeError):
                                result_data["error"] = text
                        # Attach chart_spec from captured render_chart
                        # input so the frontend can render the chart.
                        # Only attach when the tool returned success — do
                        # NOT render a chart when the tool returned an
                        # error (e.g. empty traces), as the LLM expects
                        # the chart to have failed and may put its
                        # analysis in thinking instead of text output.
                        if tool_id in tool_chart_specs and "chart_spec" not in result_data and "error" not in result_data:
                            result_data["chart_spec"] = tool_chart_specs[tool_id]
                        # Detect subagent result (Task tool)
                        if name == "sql-analyst":
                            end_data: dict = {"id": tool_id, "name": name}
                            sql_data = subagent_sql_data.get(tool_id, [])
                            if sql_data:
                                end_data["sql_results"] = [
                                    {k: v for k, v in entry.items() if k != "tool_id"}
                                    for entry in sql_data
                                ]
                            narrative = subagent_texts.get(tool_id, "") or tool_use_result_text
                            if narrative:
                                end_data["result"] = narrative
                            # Track subagent_end segment for persistence
                            persisted_segments.append({
                                "type": "subagent_end",
                                "subagentId": tool_id,
                                "subagentName": name,
                                "text": narrative or None,
                                "sqlResults": end_data.get("sql_results"),
                            })
                            yield f"event: subagent_end\ndata: {json.dumps(end_data, default=str)}\n\n"
                            continue
                        # Accumulate SQL and chart data for persistence
                        if "columns" in result_data and "rows" in result_data:
                            assistant_metadata["sql_queries"].append({
                                "sql": result_data.get("sql", ""),
                                "columns": result_data.get("columns", []),
                                "rowCount": result_data.get("rowCount", 0),
                            })
                        if "chart_spec" in result_data:
                            assistant_metadata["chart_specs"].append(result_data["chart_spec"])
                        # Update tool segment with result summary
                        for seg in persisted_segments:
                            if seg.get("type") == "tool" and seg.get("toolCallId") == tool_id:
                                seg["rowCount"] = result_data.get("rowCount")
                                seg["error"] = result_data.get("error")
                                if "chart_spec" in result_data:
                                    seg["chart_spec"] = result_data["chart_spec"]
                                break
                        yield f"event: tool_result\ndata: {json.dumps(result_data, default=str)}\n\n"

                # --- Final result ---
                elif msg_type == "result":
                    actual_session_id = msg.get("session_id") or actual_session_id
                    if msg.get("is_error"):
                        errors = msg.get("errors", [])
                        error_text = msg.get("result") or "; ".join(errors) or "Unknown error"
                        yield f"event: error\ndata: {json.dumps({'message': error_text})}\n\n"
                    yield f"event: done\ndata: {json.dumps({'session_id': actual_session_id})}\n\n"
                    done_sent = True

                # --- Sidecar error (e.g. SDK/CLI crash inside container) ---
                elif msg_type == "error":
                    error_text = msg.get("message") or "Sidecar error"
                    logger.error("Sidecar reported error: %s", error_text)
                    yield f"event: error\ndata: {json.dumps({'message': error_text})}\n\n"
                    yield f"event: done\ndata: {json.dumps({'session_id': actual_session_id})}\n\n"
                    done_sent = True

                # --- Extract session_id early from system init ---
                elif msg_type == "system":
                    sys_session = msg.get("session_id")
                    if sys_session:
                        actual_session_id = sys_session

    # Guard: always send done even if sidecar ended without result message
    if not done_sent:
        logger.warning("Sidecar stream ended without result message; sending done event")
        yield f"event: error\ndata: {json.dumps({'message': 'Connection to agent was lost. Please try again.'})}\n\n"
        yield f"event: done\ndata: {json.dumps({'session_id': actual_session_id})}\n\n"

except Exception as e:
    logger.error("Container agent error: %s", str(e))
    yield f"event: error\ndata: {json.dumps({'message': str(e)})}\n\n"
finally:
    # Persist assistant message even when the client disconnects
    # (e.g. user switched conversations mid-stream).  Without this,
    # the assistant response would be lost on reload.
    text_to_persist = assistant_text_parts or all_text_parts
    if conversation_id and text_to_persist:
        try:
            # Finalize segments: flush remaining buffers
            if seg_thinking_buf:
                persisted_segments.append({"type": "thinking", "text": "".join(seg_thinking_buf)})
                seg_thinking_buf.clear()
            # Answer text: use seg_answer_buf (tracks post-thinking text)
            # or assistant_text_parts (tracks post-tool text), or fallback
            answer_text = "".join(seg_answer_buf) if seg_answer_buf else "".join(assistant_text_parts)
            if answer_text:
                persisted_segments.append({"type": "answer", "text": answer_text})
            elif all_text_parts and not persisted_segments:
                # No thinking blocks, no tool calls — all text is the answer
                persisted_segments.append({"type": "answer", "text": "".join(all_text_parts)})

            meta = assistant_metadata.copy() if (assistant_metadata["sql_queries"] or assistant_metadata["chart_specs"]) else {}
            if persisted_segments:
                meta["segments"] = persisted_segments
            memory_store.add_message(
                conversation_id, "assistant", "".join(text_to_persist),
                metadata=meta if meta else None,
            )
        except Exception:
            logger.warning("Failed to persist assistant message", exc_info=True)
# Note: Container is kept alive for session resume (--resume flag) and is
# cleaned up by the background cleanup loop after
# CONTAINER_MAX_LIFETIME_SECONDS, or on application shutdown.
